css:
.innobet-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2733;
    background: linear-gradient(160deg, #eef2f3 0%, #e7eef0 55%, #e2edec 100%);
    border-radius: 18px;
}

.innobet-container * {
    box-sizing: border-box;
}

.innobet-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #11202b 0%, #143845 52%, #0f5d54 100%);
    color: #f1faf8;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(15, 45, 56, 0.32);
}

.innobet-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.innobet-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8fe6c4;
    background: rgba(143, 230, 196, 0.12);
    border: 1px solid rgba(143, 230, 196, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.innobet-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe7e3;
}

.innobet-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.innobet-firm {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(27, 39, 51, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.innobet-firm-core { border-left: 5px solid #b06d12; }
.innobet-firm-bet { border-left: 5px solid #1f9d6b; }

.innobet-firm-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #143845;
}

.innobet-firm-core .innobet-firm-name { color: #b06d12; }
.innobet-firm-bet .innobet-firm-name { color: #157a52; }

.innobet-firm-meta {
    font-size: 0.82rem;
    color: #5a6b75;
    line-height: 1.4;
}

.innobet-firm-plus {
    align-self: center;
    font-size: 1.7rem;
    font-weight: 800;
    color: #0f5d54;
}

.innobet-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44565f;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.innobet-period-counter #currentDay,
.innobet-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f9d6b;
}

.innobet-round-name {
    background: rgba(31, 157, 107, 0.14);
    color: #157a52;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.innobet-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06d12;
    background: rgba(176, 109, 18, 0.13);
    border: 1px solid rgba(176, 109, 18, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.innobet-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.innobet-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.08);
    border-top: 4px solid #143845;
}

.innobet-card-renewal { border-top-color: #1f9d6b; }
.innobet-card-ev { border-top-color: #2c6fb0; }
.innobet-card-core { border-top-color: #b06d12; }
.innobet-card-eff { border-top-color: #6f5fc0; }

.innobet-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7c86;
}

.innobet-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #143845;
    font-variant-numeric: tabular-nums;
}

.innobet-card-renewal .innobet-value { color: #1f9d6b; }
.innobet-card-ev .innobet-value { color: #2c6fb0; }
.innobet-card-core .innobet-value { color: #b06d12; }
.innobet-card-eff .innobet-value { color: #6f5fc0; }

.innobet-sublabel {
    font-size: 0.76rem;
    color: #74868f;
    line-height: 1.35;
}

.innobet-card-renewal.innobet-renewal-good { border-top-color: #1f9d6b; }
.innobet-card-renewal.innobet-renewal-good .innobet-value { color: #1f9d6b; }
.innobet-card-renewal.innobet-renewal-bad { border-top-color: #c83a3a; }
.innobet-card-renewal.innobet-renewal-bad .innobet-value { color: #c83a3a; }

.innobet-card-core.innobet-core-bad { border-top-color: #c83a3a; }
.innobet-card-core.innobet-core-bad .innobet-value { color: #c83a3a; }

.innobet-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dbe4e5;
    color: #44565f;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.innobet-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #157a52;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.innobet-budget-bar.innobet-budget-over #budgetDisplay { color: #c83a3a; }
.innobet-budget-bar.innobet-budget-tight #budgetDisplay { color: #b06d12; }

.innobet-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f9d6b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.innobet-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.innobet-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #143845;
    margin-bottom: 6px;
}

.innobet-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4c56;
}

.innobet-briefing-text strong { color: #0f5d54; }
.innobet-briefing-text em { color: #b06d12; font-style: italic; }

.innobet-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.innobet-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #143845;
    border-bottom: 2px solid #e5ecec;
    padding-bottom: 8px;
}

.innobet-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3c46;
    margin: 14px 0 6px;
}

.innobet-container select,
.innobet-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5d1d4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1b2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.innobet-container select:focus,
.innobet-container input[type="number"]:focus {
    outline: none;
    border-color: #1f9d6b;
    box-shadow: 0 0 0 3px rgba(31, 157, 107, 0.16);
}

.innobet-container select option {
    background-color: #ffffff;
    color: #1b2733;
}

.innobet-hint {
    font-size: 0.8rem;
    color: #74868f;
    margin-top: 8px;
    line-height: 1.4;
    font-style: italic;
    background: #f3f8f6;
    border-left: 3px solid #1f9d6b;
    padding: 8px 12px;
    border-radius: 6px;
}

.innobet-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.innobet-container .btn-primary {
    background: linear-gradient(135deg, #0f5d54 0%, #1f9d6b 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 93, 84, 0.32);
}

.innobet-container .btn-primary:hover {
    filter: brightness(1.07);
}

.innobet-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c5d1d4;
    color: #5a6b75;
    background: transparent;
}

.innobet-coach {
    background: linear-gradient(160deg, #11202b 0%, #143845 100%);
    color: #e0f1ed;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(15, 45, 56, 0.26);
}

.innobet-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fe6c4;
    margin-bottom: 8px;
}

.innobet-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.innobet-coach-body strong { color: #7fe0cb; }
.innobet-coach-body em { color: #ffcf8a; font-style: italic; }

.innobet-history,
.innobet-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(27, 39, 51, 0.07);
}

.innobet-history h3,
.innobet-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #143845;
}

.innobet-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4c56;
}

.innobet-container table#usfHistoryTable th {
    background: #eef4f2;
    color: #0f5d54;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3df;
}

.innobet-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f1;
    color: #3a4c56;
}

.innobet-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf8;
}

.innobet-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .innobet-container {
        padding: 14px;
    }
    .innobet-header h1 {
        font-size: 1.7rem;
    }
    .innobet-firms {
        flex-direction: column;
    }
    .innobet-firm-plus {
        transform: rotate(90deg);
    }
    .innobet-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .innobet-value {
        font-size: 2rem;
    }
    .innobet-clock {
        margin-left: 0;
    }
    .innobet-period-counter {
        font-size: 0.88rem;
    }
    .innobet-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .innobet-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, innobet-cm-*) ===== */
.innobet-cm { color: #251f38; font-family: inherit; }
.innobet-cm-generic { font-size: 15px; text-align: center; }
.innobet-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(37,31,56,0.12); margin-bottom: 16px; }
.innobet-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #7b5ea7; }
.innobet-cm-score-max { font-size: 20px; font-weight: 500; color: #7f7891; margin-left: 2px; }
.innobet-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #251f38; }
.innobet-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #7f7891; margin-top: 4px; }
.innobet-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.innobet-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(123,94,167,0.08); border: 1px solid rgba(123,94,167,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.innobet-cm-kpi-val { display: block; font-size: 21px; font-weight: 700; color: #251f38; }
.innobet-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #575167; }
.innobet-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.innobet-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.innobet-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.innobet-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.innobet-cm-insights { margin: 0; padding-left: 18px; }
.innobet-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #38324a; margin-bottom: 7px; }

