(function() {
    'use strict';

    class InnovationBetAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Innovation Bet`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Cobalt Coatings NV). All EUR. ----
            this.ENVELOPE = 21;        // €21M annual innovation envelope (hard cap)
            this.CORE_REVENUE = 328;   // €328M solvent core (78% of €420M)
            this.RENEWAL_GAP = 105;    // ~€105M new-to-2025 revenue needed by 2031 (25% of €420M)
            this.START_CORE = 62;      // core resilience index 0–100 (eroding 4–6%/yr)
            this.WATER_NPV = 14;       // €14M incremental NPV, water-based defence
            this.BIO_MARKET = 1200;    // €1.2B EU bio-coatings market by 2030
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    renewal: 0,            // % of the renewal gap closed toward the 2031 mandate
                    ev: 0,                 // €M blended risk-adjusted NPV of the funded portfolio
                    core: this.START_CORE, // 0–100 solvent cash-engine resilience
                    eff: 0,                // value created per € of the envelope (×100)
                    committed: 0,          // €M committed against the €21M envelope
                    effShown: false,       // efficiency only meaningful once the envelope is allocated (R3)
                    // ---- sticky, run-defining error flags: once set, they CAP KPIs and GATE the verdict ----
                    wishList: false,        // funded beyond €21M (Common Error 1)
                    heroBet: false,         // poured into the bio bet, starved core defence (Common Error 2)
                    incrementalOnly: false, // safe water-based only, missed the mandate (Common Error 3)
                    ungoverned: false,      // signed NovaResin with no governance / fallback (Common Error 4)
                    cannibalIgnored: false, // ignored cannibalisation of the solvent core (Common Error 5)
                    staged: false,          // disruptive bet stage-gated with a kill point
                    partnered: false,       // NovaResin involved at all
                    builtInternal: false,   // building bio capability in-house
                    renewalHistory: [0],
                    evHistory: [0],
                    coreHistory: [this.START_CORE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults deliberately lean toward the concept's COMMON ERRORS,
                // so a blind click-through (taking the first option each round) does NOT win.
                state.decisions = {
                    horizon: `balanced`,
                    gap: `real`,
                    sustaining: `triage`,
                    tension: `ambidexterity`,
                    path: `build`,
                    governance: `protected`,
                    stress: `optioned`,
                    allocSustaining: 8,    // first option = fund the whole €8M (inertia)
                    allocIncremental: 4,
                    allocDisruptive: `staged`,
                    allocReserve: 3,
                    pitch: `portfolio`,
                    killgate: `realoptions`,
                    cannibal: `modeled`,
                    milestone: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ho = document.getElementById(`horizonInput`);
                const ga = document.getElementById(`gapInput`);
                const su = document.getElementById(`sustainingInput`);
                const te = document.getElementById(`tensionInput`);
                if (ho) decisions.horizon = ho.value;
                if (ga) decisions.gap = ga.value;
                if (su) decisions.sustaining = su.value;
                if (te) decisions.tension = te.value;
                if (!decisions.horizon || !decisions.gap || !decisions.sustaining || !decisions.tension) {
                    warn(`warn_select_all`); return false;
                }
            } else if (round === 2) {
                const pa = document.getElementById(`pathInput`);
                const go = document.getElementById(`governanceInput`);
                const st = document.getElementById(`stressInput`);
                if (pa) decisions.path = pa.value;
                if (go) decisions.governance = go.value;
                if (st) decisions.stress = st.value;
                if (!decisions.path || !decisions.governance || !decisions.stress) {
                    warn(`warn_select_all`); return false;
                }
            } else if (round === 3) {
                const aS = document.getElementById(`allocSustainingInput`);
                const aI = document.getElementById(`allocIncrementalInput`);
                const aD = document.getElementById(`allocDisruptiveInput`);
                const aR = document.getElementById(`allocReserveInput`);
                if (aS) decisions.allocSustaining = parseFloat(aS.value);
                if (aI) decisions.allocIncremental = parseFloat(aI.value);
                if (aD) decisions.allocDisruptive = aD.value;
                if (aR) decisions.allocReserve = parseFloat(aR.value);
                if (!Number.isFinite(decisions.allocSustaining) || decisions.allocSustaining < 0) {
                    warn(`warn_alloc_value`); return false;
                }
                if (!Number.isFinite(decisions.allocIncremental) || decisions.allocIncremental < 0) {
                    warn(`warn_alloc_value`); return false;
                }
                if (!Number.isFinite(decisions.allocReserve) || decisions.allocReserve < 0) {
                    warn(`warn_alloc_value`); return false;
                }
                if (!decisions.allocDisruptive) {
                    warn(`warn_select_all`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const ki = document.getElementById(`killgateInput`);
                const ca = document.getElementById(`cannibalInput`);
                const mi = document.getElementById(`milestoneInput`);
                if (pi) decisions.pitch = pi.value;
                if (ki) decisions.killgate = ki.value;
                if (ca) decisions.cannibal = ca.value;
                if (mi) decisions.milestone = parseInt(mi.value, 10);
                if (!Number.isFinite(decisions.milestone) || decisions.milestone < 0 || decisions.milestone > 100) {
                    warn(`warn_milestone_range`); return false;
                }
                if (!decisions.pitch || !decisions.killgate || !decisions.cannibal) {
                    warn(`warn_select_all`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let renewalDelta = 0, evDelta = 0, coreDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // Baseline annual core erosion (4–6%/yr substitution + REACH/VOC pressure).
            coreDelta -= 3;

            if (round === 1) {
                // ---- Diagnose the portfolio. Reading the gap and the tension correctly
                //      sets up renewal; misreading seeds comfort-zone thinking. ----
                switch (d.horizon) {
                    case `balanced`: renewalDelta += 8; coreDelta += 1; coachKey = `coach_r1_balanced`; break;
                    case `fine`: renewalDelta -= 4; coachKey = `coach_r1_fine`; break;
                    case `h3only`: renewalDelta += 2; coreDelta -= 4; coachKey = `coach_r1_h3only`; break;
                }
                switch (d.gap) {
                    case `real`: renewalDelta += 10; coachKey = `coach_r1_gapreal`; break;
                    case `small`: renewalDelta -= 5; ds.incrementalOnly = true; coachKey = `coach_r1_gapsmall`; break;
                    case `none`: renewalDelta -= 10; ds.incrementalOnly = true; coachKey = `coach_r1_gapnone`; break;
                }
                switch (d.sustaining) {
                    case `triage`: renewalDelta += 2; evDelta += 2; coreDelta += 3; break;
                    case `keepall`: evDelta -= 1; coreDelta += 1; break;          // inertia funded
                    case `cutall`: coreDelta -= 6; coachKey = `coach_r1_cutall`; break; // strips the cash engine
                }
                switch (d.tension) {
                    case `ambidexterity`: renewalDelta += 8; coreDelta += 2; if (d.gap === `real` && d.horizon === `balanced`) coachKey = `coach_r1_sharp`; break;
                    case `growth`: renewalDelta -= 2; break;
                    case `cost`: renewalDelta -= 6; ds.incrementalOnly = true; coachKey = `coach_r1_cost`; break;
                }

                summaryKey = (d.horizon === `balanced` && d.gap === `real` && d.sustaining === `triage` && d.tension === `ambidexterity`)
                    ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Build vs open innovation. Governance & stress-testing decide whether
                //      a partnership is protected or exposed (Common Error 4). ----
                switch (d.path) {
                    case `build`:
                        ds.builtInternal = true;
                        renewalDelta += 5; evDelta += 3; coreDelta -= 1;
                        coachKey = `coach_r2_build`;
                        break;
                    case `partner`:
                        ds.partnered = true;
                        renewalDelta += 15; evDelta += 5;   // speed + a working TRL-6 resin
                        coachKey = `coach_r2_partner`;
                        break;
                    case `hybrid`:
                        ds.partnered = true; ds.builtInternal = true;
                        renewalDelta += 18; evDelta += 7;  // speed of the partner + retained capability
                        coachKey = `coach_r2_hybrid`;
                        break;
                    case `none`:
                        ds.incrementalOnly = true;
                        renewalDelta -= 8;
                        coachKey = `coach_r2_none`;
                        break;
                }

                switch (d.governance) {
                    case `protected`:
                        evDelta += 4;
                        // a board seat, change-of-control clause and IP fallback protect Cobalt
                        if (ds.partnered) { renewalDelta += 3; coachKey = `coach_r2_protected`; }
                        break;
                    case `equity`:
                        evDelta += 2; coreDelta -= 2;  // €18M one-move bite (governs envelope pressure later)
                        break;
                    case `armslength`:
                        if (ds.partnered) { ds.ungoverned = true; evDelta -= 4; coachKey = `coach_r2_armslength`; }
                        break;
                    case `na`:
                        // building in-house or not betting — no partner governance needed.
                        break;
                }

                switch (d.stress) {
                    case `optioned`: ds.staged = true; renewalDelta += 2; evDelta += 3; coreDelta += 1; break;
                    case `diversified`: evDelta += 2; coreDelta += 1; break;
                    case `hope`:
                        if (ds.partnered) { ds.ungoverned = true; coachKey = `coach_r2_hope`; }
                        evDelta -= 3;
                        break;
                }

                summaryKey = ((d.path === `hybrid` || d.path === `partner`) && d.governance === `protected` && d.stress === `optioned`)
                    ? `sum_r2_good`
                    : (ds.ungoverned ? `sum_r2_ungoverned`
                    : (d.path === `none` ? `sum_r2_none` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Allocate the €21M envelope. The hard cap. ----
                const sus = Number(d.allocSustaining) || 0;
                const inc = Number(d.allocIncremental) || 0;
                let dis = 0;
                if (d.allocDisruptive === `full`) dis = 9;
                else if (d.allocDisruptive === `staged`) dis = 6;
                else if (d.allocDisruptive === `partner`) dis = 6;
                else dis = 0;
                const res = Number(d.allocReserve) || 0;
                const total = sus + inc + dis + res;
                ds.committed = Math.round(total * 10) / 10;

                // (1) Wish-list overspend beyond €21M — the headline anti-pattern.
                if (total > this.ENVELOPE + 0.001) {
                    ds.wishList = true;
                    evDelta -= 8; renewalDelta -= 6;
                    coachKey = `coach_r3_wishlist`;
                }

                // Incremental water-based defence (85% success, €14M NPV) defends the core.
                if (inc >= 4) { coreDelta += 9; evDelta += 4; }
                else if (inc >= 2) { coreDelta += 4; evDelta += 2; }
                else { coreDelta -= 2; }

                // Sustaining commitments protect near-term margin; cutting all strips the engine.
                if (sus >= 8) { coreDelta += 3; evDelta -= 1; }       // funds the inertia too
                else if (sus >= 5) { coreDelta += 4; evDelta += 1; }  // triaged — strategic kept
                else if (sus >= 3) { coreDelta += 1; }
                else { coreDelta -= 5; }

                // The disruptive bet drives renewal.
                if (d.allocDisruptive === `full`) {
                    ds.staged = false;
                    renewalDelta += 32;
                    // (2) Hero-bet concentration: full €9M build AND no incremental defence.
                    if (inc <= 0) {
                        ds.heroBet = true;
                        coreDelta -= 8; evDelta -= 6;
                        coachKey = `coach_r3_herobet`;
                    } else {
                        coachKey = `coach_r3_full`;
                    }
                } else if (d.allocDisruptive === `staged`) {
                    ds.staged = true;
                    renewalDelta += 28; evDelta += 5;   // buys information, caps downside
                    if (coachKey === `coach_default`) coachKey = `coach_r3_staged`;
                } else if (d.allocDisruptive === `partner`) {
                    ds.partnered = true;
                    renewalDelta += 30; evDelta += 4;   // partner speed feeds the gap
                    if (ds.ungoverned) { evDelta -= 4; }
                    if (coachKey === `coach_default`) coachKey = `coach_r3_partner`;
                } else {
                    // (3) Comfort-zone incrementalism: no disruptive bet funded.
                    ds.incrementalOnly = true;
                    renewalDelta -= 12;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_nobet`;
                }

                // Reserve = dry powder for the kill-gate tranche / an emerging H2 option.
                if (res >= 3 && total <= this.ENVELOPE) { evDelta += 3; coreDelta += 1; }
                else if (res >= 1 && total <= this.ENVELOPE) { evDelta += 1; }

                // Efficiency = value created per € committed against the envelope.
                ds.effShown = true;

                if (ds.wishList) summaryKey = `sum_r3_wishlist`;
                else if (ds.heroBet) summaryKey = `sum_r3_herobet`;
                else if (d.allocDisruptive === `0`) summaryKey = `sum_r3_nobet`;
                else if (total <= this.ENVELOPE && inc >= 2 && (d.allocDisruptive === `staged` || d.allocDisruptive === `partner`)) summaryKey = `sum_r3_good`;
                else summaryKey = `sum_r3_weak`;
            } else if (round === 4) {
                // ---- Defend the bet to the board. Cannibalisation & kill criteria. ----
                switch (d.pitch) {
                    case `portfolio`: renewalDelta += 8; evDelta += 3; coreDelta += 2; coachKey = `coach_r4_portfolio`; break;
                    case `hero`:
                        ds.heroBet = true;
                        renewalDelta += 4; coreDelta -= 4; evDelta -= 3;
                        coachKey = `coach_r4_hero`;
                        break;
                    case `safe`:
                        ds.incrementalOnly = true;
                        renewalDelta -= 6; coreDelta += 2;
                        coachKey = `coach_r4_safe`;
                        break;
                }
                switch (d.killgate) {
                    case `realoptions`: ds.staged = true; evDelta += 5; renewalDelta += 5; break;
                    case `conviction`: ds.staged = false; evDelta -= 4; coreDelta -= 2; coachKey = `coach_r4_conviction`; break;
                    case `nogate`: ds.incrementalOnly = true; renewalDelta -= 4; break;
                }
                switch (d.cannibal) {
                    case `modeled`: coreDelta += 6; evDelta += 4; break;
                    case `separate`:
                        ds.cannibalIgnored = true;
                        coreDelta -= 6; evDelta -= 3;
                        coachKey = `coach_r4_cannibalseparate`;
                        break;
                    case `ignore`:
                        ds.cannibalIgnored = true;
                        coreDelta -= 9; evDelta -= 5;
                        coachKey = `coach_r4_cannibalignore`;
                        break;
                }

                // 12-month milestone conviction in the staged-renewal logic.
                if (d.milestone >= 60) { evDelta += 3; renewalDelta += 4; }
                else if (d.milestone <= 25) { evDelta -= 2; renewalDelta -= 3; }

                summaryKey = (d.pitch === `portfolio` && d.killgate === `realoptions` && d.cannibal === `modeled`)
                    ? `sum_r4_good`
                    : (ds.cannibalIgnored ? `sum_r4_cannibal`
                    : (d.pitch === `hero` ? `sum_r4_hero`
                    : (d.pitch === `safe` ? `sum_r4_safe` : `sum_r4_weak`)));
            }

            // ---- Apply deltas. ----
            ds.renewal = Math.max(0, Math.round((ds.renewal + renewalDelta) * 10) / 10);
            ds.ev = Math.round((ds.ev + evDelta) * 10) / 10;
            ds.core = Math.max(0, Math.min(100, Math.round((ds.core + coreDelta) * 10) / 10));

            // ---- Sticky-flag CAPS: a run-defining error caps the headline KPIs no matter
            //      how clean the other rounds were. This is what stops an anti-pattern winning. ----
            if (ds.wishList) {
                ds.renewal = Math.min(ds.renewal, 70);
                ds.ev = Math.min(ds.ev, 8);
            }
            if (ds.heroBet) {
                ds.core = Math.min(ds.core, 42);      // starved core defence
                ds.ev = Math.min(ds.ev, 9);           // 50% failure probability, no hedge
            }
            if (ds.incrementalOnly) {
                ds.renewal = Math.min(ds.renewal, 55); // defends, does not renew — misses the mandate
            }
            if (ds.ungoverned) {
                ds.ev = Math.min(ds.ev, 7);            // exposed to a competitor acquisition of NovaResin
            }
            if (ds.cannibalIgnored) {
                ds.core = Math.min(ds.core, 44);       // cash engine erodes faster than projected
            }

            // ---- Resource efficiency: value (EV, scaled to the gap) created per € of envelope. ----
            if (ds.effShown) {
                const evScore = Math.max(0, Math.min(100, (ds.ev / 18) * 100));
                const renewScore = Math.max(0, Math.min(100, ds.renewal));
                const value = (evScore * 0.55 + renewScore * 0.45);
                const spend = ds.committed > 0 ? ds.committed : this.ENVELOPE;
                // index 0–100: value per €M, normalised so a clean in-budget portfolio lands high.
                ds.eff = Math.max(0, Math.min(100, Math.round((value / spend) * this.ENVELOPE)));
                if (ds.wishList) ds.eff = Math.min(ds.eff, 35); // overspend is a wish list, not a plan
            }

            ds.renewalHistory.push(ds.renewal);
            ds.evHistory.push(ds.ev);
            ds.coreHistory.push(ds.core);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                renewal: ds.renewal,
                renewalDelta: Math.round(renewalDelta * 10) / 10,
                ev: ds.ev,
                evDelta: Math.round(evDelta * 10) / 10,
                core: ds.core,
                coreDelta: Math.round(coreDelta * 10) / 10,
                eff: ds.eff,
                committed: ds.committed,
                wishList: ds.wishList,
                heroBet: ds.heroBet,
                incrementalOnly: ds.incrementalOnly,
                ungoverned: ds.ungoverned,
                cannibalIgnored: ds.cannibalIgnored,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`renewalDisplay`, `domainState.renewal`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.innobet-card-renewal`);
                if (card) {
                    card.classList.toggle(`innobet-renewal-good`, n >= 95);
                    card.classList.toggle(`innobet-renewal-bad`, n < 60);
                }
                return `${n}%`;
            });

            uiManager.bind(`evDisplay`, `domainState.ev`, (v) => self._fmtMoney(Number(v)));

            uiManager.bind(`coreDisplay`, `domainState.core`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.innobet-card-core`);
                if (card) card.classList.toggle(`innobet-core-bad`, n < 50);
                return `${n}`;
            });

            uiManager.bind(`effDisplay`, `domainState.eff`, (v) => {
                const ds = window.mySimulation.state.domainState;
                if (!ds || !ds.effShown) return `—`;
                return `${Math.round(Number(v))}`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.committed`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.innobet-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`innobet-budget-over`, n > self.ENVELOPE + 0.001);
                    bar.classList.toggle(`innobet-budget-tight`, n > self.ENVELOPE - 1.5 && n <= self.ENVELOPE + 0.001);
                }
                return `${self._fmtMoney(n)} / €${self.ENVELOPE}M`;
            });
        }

        _fmtMoney(v) {
            // Locale-aware €M: en "€14.0M", es "€14,0M".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return `€` + (lang === `es` ? s.replace(`.`, `,`) : s) + `M`;
        }

