        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.renewalHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                innobetChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.renewalHistory.map((v) => Math.round(v)) },
                        { data: ds.coreHistory.map((v) => Math.round(v)) },
                        { data: ds.evHistory.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const renewal = Math.round(ds.renewal);
            const ev = Math.round(ds.ev * 10) / 10;
            const core = Math.round(ds.core);
            const eff = Math.round(ds.eff);
            const renewalScore = Math.max(0, Math.min(100, renewal));
            const evScore = Math.max(0, Math.min(100, (ev / 18) * 100));
            return Math.round(renewalScore * 0.32 + evScore * 0.26 + core * 0.24 + Math.min(100, eff) * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const renewal = Math.round(ds.renewal);
            const ev = Math.round(ds.ev * 10) / 10;
            const core = Math.round(ds.core);
            const eff = Math.round(ds.eff);

            const composite = this._composite(ds);

            const mandateMet = renewal >= 95;
            const valuable = ev >= 16;
            const coreHeld = core >= 60;
            const efficient = eff >= 60;
            const anyError = ds.wishList || ds.heroBet || ds.incrementalOnly || ds.ungoverned || ds.cannibalIgnored;

            // ---- Top verdict GATE: only a clean, in-budget, balanced 4-round playthrough
            //      with NO sticky error flag reaches "Renewal Portfolio". ----
            let performance = `Graceful Decline`, performanceKey = `grade_decline`;
            if (mandateMet && valuable && coreHeld && efficient && !anyError && composite >= 80) {
                performance = `Renewal Portfolio`; performanceKey = `grade_renewal`;
            } else if (ds.wishList) {
                performance = `Wish List`; performanceKey = `grade_wishlist`;
            } else if (ds.heroBet) {
                performance = `Hero Bet`; performanceKey = `grade_herobet`;
            } else if (ds.incrementalOnly) {
                performance = `Comfort Zone`; performanceKey = `grade_comfort`;
            } else if (ds.ungoverned) {
                performance = `Ungoverned Partnership`; performanceKey = `grade_ungoverned`;
            } else if (ds.cannibalIgnored) {
                performance = `Cannibalised Core`; performanceKey = `grade_cannibal`;
            } else if (composite >= 60) {
                performance = `Credible Plan`; performanceKey = `grade_credible`;
            }

            const insights = [];
            if (performance === `Renewal Portfolio`) insights.push(window.mySimulation.t(`insight_renewal`));
            if (ds.wishList) insights.push(window.mySimulation.t(`insight_wishlist`));
            if (ds.heroBet) insights.push(window.mySimulation.t(`insight_herobet`));
            if (ds.incrementalOnly) insights.push(window.mySimulation.t(`insight_incremental`));
            if (ds.ungoverned) insights.push(window.mySimulation.t(`insight_ungoverned`));
            if (ds.cannibalIgnored) insights.push(window.mySimulation.t(`insight_cannibal`));
            if (!anyError && performance !== `Renewal Portfolio`) insights.push(window.mySimulation.t(`insight_mixed`));
            if (ds.staged) insights.push(window.mySimulation.t(`insight_staged`));

            return {
                renewal: renewal,
                ev: ev,
                core: core,
                eff: eff,
                composite: composite,
                performanceKey: performanceKey,
                mandateMet: mandateMet,
                valuable: valuable,
                coreHeld: coreHeld,
                efficient: efficient,
                wishList: ds.wishList,
                heroBet: ds.heroBet,
                incrementalOnly: ds.incrementalOnly,
                ungoverned: ds.ungoverned,
                cannibalIgnored: ds.cannibalIgnored,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="innobet-cm"><p class="innobet-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="innobet-cm-kpi"><span class="innobet-cm-kpi-val">${valStr}</span>`
                + `<span class="innobet-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="innobet-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="innobet-cm">`
                +   `<div class="innobet-cm-scoreband">`
                +     `<div class="innobet-cm-score">${summary.composite}<span class="innobet-cm-score-max">/100</span></div>`
                +     `<div class="innobet-cm-tier">${tier}</div>`
                +     `<div class="innobet-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="innobet-cm-kpis">`
                +     kpi(`cm_kpi_renewal`, String(Math.round(summary.renewal)) + `%`)
                +     kpi(`cm_kpi_ev`, self._fmtMoney(summary.ev))
                +     kpi(`cm_kpi_core`, String(Math.round(summary.core)))
                +     kpi(`cm_kpi_eff`, String(Math.round(summary.eff)) + `%`)
                +   `</div>`
                +   `<div class="innobet-cm-chips">`
                +     chip(summary.mandateMet, `cm_chip_mandate`)
                +     chip(summary.valuable, `cm_chip_value`)
                +     chip(summary.coreHeld, `cm_chip_core`)
                +     chip(summary.efficient, `cm_chip_eff`)
                +   `</div>`
                +   (insights ? `<ul class="innobet-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.wishList) return window.mySimulation.t(`hint_wishlist`);
            if (ds.heroBet) return window.mySimulation.t(`hint_herobet`);
            if (ds.cannibalIgnored) return window.mySimulation.t(`hint_cannibal`);
            if (ds.ungoverned) return window.mySimulation.t(`hint_ungoverned`);
            if (ds.incrementalOnly && state.currentPeriod >= 2) return window.mySimulation.t(`hint_incremental`);
            if (ds.core < 50) return window.mySimulation.t(`hint_core`);
            if (ds.renewal >= 90 && ds.core >= 60 && !ds.wishList && !ds.heroBet) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.renewal`, label: `Renewal`, i18nKey: `col_renewal`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.ev`, label: `EV`, i18nKey: `col_ev`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.core`, label: `Core`, i18nKey: `col_core`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `The Innovation Bet`,
                    subtitle:               `You are the new General Manager of a €420M specialty-coatings maker whose solvent-based core — 78% of revenue — is eroding under REACH and VOC pressure. The board demands 25% of revenue from products that did not exist in 2025, by 2031. You have one planning cycle and a €21M envelope to place the bets that decide renewal or graceful decline.`,
                    header_tag:             `14 January 2026 · Cobalt Coatings NV · Brussels · Board strategic-renewal mandate`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Renewal Coverage, Portfolio Value & Core Resilience`,
                    chart_start:            `Start`,
                    coach_header:           `The Board (playing the strategic-renewal committee)`,
                    coach_intro:            `You inherit a pipeline that is 92% incremental and a mandate to make a quarter of the company new by 2031. The envelope is €21M and it does not stretch to everything. Spend past it and it is a wish list, not a portfolio. Pour it all into the bio bet and you starve the core that funds the renewal. Stay safe and you miss the mandate. Show us a portfolio — what you fund, what you cut, and what you would kill at month 12.`,

                    firm_core:              `Solvent Core (H1)`,
                    firm_core_meta:         `€328M · 78% of revenue · declining 4–6%/yr · the cash engine that funds everything`,
                    firm_bet:               `Bio-Resin Platform (H3)`,
                    firm_bet_meta:          `€1.2B EU market by 2030 · 45–55% technical success · 4+ years to revenue · the renewal bet`,

                    renewal_label:          `Renewal Coverage`,
                    renewal_sub:            `Progress to the 25%-new-revenue mandate by 2031 · target = 100% of the gap closed`,
                    ev_label:               `Portfolio Expected Value`,
                    ev_sub:                 `Blended risk-adjusted NPV of the funded portfolio · the value the bets actually create`,
                    core_label:             `Core Resilience`,
                    core_sub:               `Health of the solvent cash engine (0–100) · defended and cannibalisation managed`,
                    eff_label:              `Resource Efficiency`,
                    eff_sub:                `Value created per € of the €21M envelope · spending beyond it is a wish list, not a plan`,
                    budget_label:           `Innovation envelope committed`,

                    clock_r1:               `Week 1 · 8 weeks to the March board meeting`,
                    clock_r2:               `Weeks 2–3 · build vs open innovation`,
                    clock_r3:               `Weeks 4–6 · allocate the €21M`,
                    clock_r4:               `Weeks 7–8 · defend the bet to the board`,

                    round_name_r1:          `Diagnose the Portfolio`,
                    round_name_r2:          `Build vs Open Innovation`,
                    round_name_r3:          `Allocate the Envelope`,
                    round_name_r4:          `Defend the Bet`,

                    briefing_title_r1:      `Round 1 — Diagnose the portfolio`,
                    briefing_text_r1:       `It is January 2026 at Cobalt Coatings. The board has issued a <strong>strategic-renewal mandate</strong>: at least <strong>25% of revenue from products that did not exist in 2025, by 2031</strong>. You inherit a pipeline that is <strong>92% incremental</strong> and a solvent core — €328M, 78% of revenue — declining <em>4–6% a year</em> under REACH and VOC pressure. Read the portfolio against the <strong>Three Horizons</strong>, quantify the <em>renewal gap</em> (~€105M of new revenue needed), triage the €8M of committed sustaining work, and name the central tension in one sentence.`,
                    briefing_title_r2:      `Round 2 — Build vs open innovation`,
                    briefing_text_r2:       `The bio-resin platform is the renewal bet. <strong>Build in-house</strong> (€9M/yr, 45–55% technical success, 4+ years) gives full IP and full margin but is slow and high-variance. <strong>Open innovation with NovaResin</strong> — a Ghent spin-off at TRL 6 — co-develops at €6M/yr, saving ~2 years, but cedes IP control and 40% of platform margin; a €18M equity option for 30% deepens the commitment. Choose build, partner or hybrid — then set the <em>governance</em> (board seat, change-of-control, IP fallback) and <em>stress-test</em> what protects you if NovaResin is acquired or the chemistry fails.`,
                    briefing_title_r3:      `Round 3 — Allocate the €21M envelope`,
                    briefing_text_r3:       `Now fund a coherent portfolio inside the <strong>€21M envelope — a hard cap</strong>. Allocate across sustaining commitments (€8M baseline, partly cuttable), the incremental <strong>water-based defence</strong> (€4M, 85% success, €14M NPV), the <strong>disruptive bio bet</strong> (€9M full build, or €6M staged with a kill gate, or €6M to the NovaResin partnership) and a discretionary reserve. You cannot fund everything. <em>Spend past €21M and it is a wish list; pour it into the bet and you starve the core; stay safe and you miss the mandate.</em>`,
                    briefing_title_r4:      `Round 4 — Defend the bet to the board`,
                    briefing_text_r4:       `Present the portfolio to the board. Lead with a balanced story or your single biggest bet, justify its <strong>kill criteria</strong> (a real-options stage gate at month 12), and address the question that decides the meeting: does winning in bio-coatings <em>cannibalise</em> the solvent core that funds the renewal, and did you model it? Commit to the 12-month milestones the board can hold you to.`,

                    r1_horizon_label:       `How do you read the pipeline against the Three Horizons?`,
                    horizon_balanced:       `It is 92% H1 incremental — the pipeline defends the core but holds almost no H2/H3 options; the renewal gap is structural, not cosmetic`,
                    horizon_fine:           `It is broadly fine — eleven active projects is a full pipeline; renewal will come from the projects already running`,
                    horizon_h3only:         `The H1 work is the problem — kill the incremental projects and pour everything into future bets`,
                    r1_gap_label:           `Quantify the renewal gap the board mandate creates.`,
                    gap_real:               `~€105M+ of new-to-2025 revenue is needed by 2031, and the current pipeline can credibly deliver almost none of it — the gap is large and real`,
                    gap_small:              `A modest gap — a few percent of revenue; incremental reformulation will mostly cover it`,
                    gap_none:               `No real gap — the 25% target is board theatre; the core will keep paying the bills`,
                    r1_sustaining_label:    `Which of the €8M committed sustaining projects are genuinely strategic?`,
                    sustaining_triage:      `Triage them — some defend real customers and margin; others are pipeline inertia that should be cut to free funding for renewal`,
                    sustaining_keepall:     `Keep all of them — they are committed and cutting any of them upsets the business units`,
                    sustaining_cutall:      `Cut all of them — sustaining work is the past; redirect the entire €8M to the future`,
                    r1_tension_label:       `State the central tension in one sentence.`,
                    tension_ambidexterity:  `Defend a declining cash engine and build its replacement at the same time, from one envelope that cannot fund both fully — exploit and explore together`,
                    tension_growth:         `Just grow faster — find the highest-return projects and fund them, horizons aside`,
                    tension_cost:           `Cut R&D cost — the envelope is too big for a declining business; the tension is overspending`,

                    r2_path_label:          `The bio-resin platform: build, partner, or hybrid?`,
                    path_build:             `Build in-house — €9M/yr, 45–55% technical success, 4+ years to revenue; full IP and full margin, but slow and high-variance`,
                    path_partner:           `Open innovation with NovaResin — co-develop at €6M/yr from a working TRL-6 resin; ~2 years faster, but cede IP control and 40% of platform margin`,
                    path_hybrid:            `Hybrid — partner with NovaResin to buy speed and an option, while building selective internal capability so Cobalt is not hollowed out`,
                    path_none:              `Neither — the bio bet is too risky; defend the core and revisit in a few years`,
                    r2_governance_label:    `Open-innovation governance — if you involve NovaResin, on what terms?`,
                    governance_protected:   `Co-develop with a board seat, a change-of-control clause and an IP fallback / licence-back — protect Cobalt if NovaResin is acquired or fails`,
                    governance_equity:      `Take the €18M 30% equity option — deepest commitment and most control, but it eats a large slice of the envelope in one move`,
                    governance_armslength:  `Arms-length co-development — sign for speed, keep it simple, no board seat or change-of-control protection`,
                    governance_na:          `Not applicable — we are building in-house or not betting, so no partner governance is needed`,
                    r2_stress_label:        `Stress-test: if NovaResin is acquired by a competitor or the platform fails technically, what protects you?`,
                    stress_optioned:        `A staged commitment with kill points and contractual fallback means a failure or acquisition costs us an option premium, not the platform`,
                    stress_diversified:     `Internal capability and the incremental defence keep renewal alive even if the bio bet dies`,
                    stress_hope:            `It will not happen — NovaResin is committed and the chemistry will scale; no fallback needed`,

                    r3_intro:               `Allocate the €21M envelope. Sustaining and the disruptive bet share one pool — you cannot fund everything.`,
                    r3_sustaining_label:    `Sustaining commitments — €8M baseline, partly cuttable (€M)`,
                    alloc_sus_8:            `€8M — fund every committed sustaining project, including the inertia`,
                    alloc_sus_5:            `€5M — keep the genuinely strategic sustaining work, cut the inertia`,
                    alloc_sus_3:            `€3M — keep only the few must-fund customer commitments`,
                    alloc_sus_0:            `€0M — cut all sustaining work`,
                    r3_incremental_label:   `Incremental water-based defence — 85% success, 18 months, €14M NPV (€M)`,
                    alloc_inc_4:            `€4M — fully fund the water-based defence of the core`,
                    alloc_inc_2:            `€2M — half-fund it; slower, partial defence`,
                    alloc_inc_0:            `€0M — skip core defence and bet on the future alone`,
                    r3_disruptive_label:    `The disruptive bio bet — sequence and size it (€M)`,
                    alloc_dis_staged:       `€6M staged — a first tranche with a 12-month kill gate; buy information before committing the rest`,
                    alloc_dis_full:         `€9M full build, all-in for the year — no kill point, maximum commitment`,
                    alloc_dis_partner:      `€6M to the NovaResin co-development — speed via the partnership chosen in Round 2`,
                    alloc_dis_0:            `€0M — do not fund the bio bet this cycle`,
                    r3_reserve_label:       `Discretionary reserve held back for the year (€M)`,
                    alloc_res_3:            `€3M reserve — dry powder for the kill-gate tranche or an emerging H2 option`,
                    alloc_res_1:            `€1M reserve — a thin buffer`,
                    alloc_res_0:            `€0M reserve — commit the whole envelope now`,
                    r3_alloc_hint:          `Sustaining + incremental + disruptive + reserve must stay within €21M. Spending beyond the envelope is the wish-list error — the board funds €21M and no more.`,

                    r4_pitch_label:         `Your board pitch — what do you lead with?`,
                    pitch_portfolio:        `A balanced portfolio — the core is defended, a sized renewal bet is staged with kill gates, and the plan closes the mandate gap on credible numbers`,
                    pitch_hero:             `The big bet — bio-resin is the future; we have gone all-in and the upside is enormous`,
                    pitch_safe:             `Prudence — we defended the core with low-risk water-based reformulation and avoided speculative bets`,
                    r4_killgate_label:      `Justify the single biggest bet and its kill criteria.`,
                    killgate_realoptions:   `A real-options stage gate at month 12 — defined technical and commercial milestones; if the resin does not scale, we kill the tranche and redeploy the reserve`,
                    killgate_conviction:    `Conviction — we believe in the science and have committed fully; a kill gate would only signal doubt`,
                    killgate_nogate:        `No single big bet to defend — we stayed incremental, so there is little to kill`,
                    r4_cannibal_label:      `Address cannibalisation: does winning in bio-coatings shrink the solvent core faster?`,
                    cannibal_modeled:       `Yes — we modelled it: bio success accelerates solvent decline, so we sequenced the bet and the defence so new revenue covers the loss before it bites`,
                    cannibal_separate:      `No — the two are separate businesses; the bio platform serves new customers and does not touch the solvent base`,
                    cannibal_ignore:        `We did not model the core erosion — the cash engine will keep running while the new business grows`,
                    r4_milestone_label:     `12-month commitment: how firmly do you hold the board to the staged-renewal logic? (%)`,

                    warn_select_all:        `Please make a choice for every decision this round.`,
                    warn_alloc_value:       `Each allocation must be zero or a positive number of € millions.`,
                    warn_milestone_range:   `The milestone commitment must be a percentage between 0 and 100.`,

                    coach_default:          `Decision logged.`,
                    coach_r1_balanced:      `<strong>That is the honest read.</strong> A 92% H1 pipeline defends the core and holds almost no H2/H3 options — the renewal gap is structural, not cosmetic. Naming that is the first move; you cannot allocate against a gap you have not sized.`,
                    coach_r1_fine:          `<strong>“Eleven projects is a full pipeline” is the comfort-zone read.</strong> A full pipeline of incremental reformulation defends the core; it does not renew it. The board did not ask for activity — it asked for 25% new revenue by 2031, and almost none of this pipeline delivers it.`,
                    coach_r1_h3only:        `<strong>Killing the H1 work to fund the future is the hero move, not the portfolio move.</strong> The solvent core funds 78% of the company and pays for the very renewal you are proposing. Starve it and you cut off the cash engine before the bet can pay back.`,
                    coach_r1_gapreal:       `<strong>~€105M is the right order of magnitude.</strong> A quarter of €420M, and the current pipeline can credibly deliver almost none of it. A gap that large is a portfolio problem, not a marketing one — it has to be funded and sequenced.`,
                    coach_r1_gapsmall:      `<strong>“A modest gap incremental work will cover” is the Innovator's Dilemma talking.</strong> Reformulation defends the core; it does not create new-to-2025 revenue. Size the gap honestly — it is ~€105M — or you will plan for the wrong number all the way to the board.`,
                    coach_r1_gapnone:       `<strong>“The 25% target is board theatre” is how firms manage a graceful decline.</strong> The core is eroding 4–6% a year and faces tightening REACH/VOC limits. Treat the mandate as theatre and the March meeting appoints a Chief Transformation Officer above you.`,
                    coach_r1_cutall:        `<strong>Cutting every sustaining project to fund the future strips the cash engine.</strong> Some of that €8M defends real customers and margin you need this year. Triage it — cut the inertia, keep the strategic work — rather than torching the lot.`,
                    coach_r1_cost:          `<strong>“The tension is overspending, cut R&D” inverts the problem.</strong> The €21M is the envelope that has to renew the company, not waste to be trimmed. Frame the tension as cost and you will under-invest in the renewal the board mandated.`,
                    coach_r1_sharp:         `<strong>Sharp diagnosis.</strong> You read the pipeline as structurally over-weighted to H1, sized the ~€105M gap honestly, and framed the tension as ambidexterity — defend the core and build its replacement from one envelope. That is exactly the lens the rest of the plan needs.`,
                    coach_r2_build:         `<strong>Building in-house keeps full IP and full margin — and accepts the slow, high-variance path.</strong> €9M/yr, 45–55% success, 4+ years to revenue. Defensible, but you are buying control at the price of time, and time is what the 2031 mandate is short of.`,
                    coach_r2_partner:       `<strong>Open innovation with NovaResin buys ~2 years from a working TRL-6 resin.</strong> Good instinct on speed. The price is IP control and 40% of platform margin — which is fine <em>if</em> you govern the deal. The next two choices decide whether the partnership is protected or exposed.`,
                    coach_r2_hybrid:        `<strong>Hybrid is the ambidextrous answer.</strong> Partner for the ~2-year speed and the option, while building selective internal capability so Cobalt is not hollowed out if the relationship ends. You keep a path of your own and still close the gap faster — provided the governance holds.`,
                    coach_r2_none:          `<strong>“The bio bet is too risky, revisit later” is comfort-zone incrementalism.</strong> The H3 option is exactly where the 25% renewal comes from. Defend the core and wait, and you will arrive at the March board meeting with no credible renewal plan at all.`,
                    coach_r2_protected:     `<strong>That is open-innovation governance done right.</strong> A board seat, a change-of-control clause and an IP fallback mean that if a competitor buys NovaResin or the chemistry stalls, you own a protected option — not an exposed cheque. Speed bought with protection, not instead of it.`,
                    coach_r2_armslength:    `<strong>Arms-length co-development for speed, with no governance, is the ungoverned-partnership trap.</strong> No board seat, no change-of-control clause, no IP fallback. Eighteen months in, a German competitor acquires NovaResin — what do you own, and what was the money you spent buying?`,
                    coach_r2_hope:          `<strong>“It will not happen, no fallback needed” is hope as a strategy.</strong> NovaResin sits at TRL 6 in an attractive market — exactly the kind of spin-off a competitor acquires. Without a kill point and a contractual fallback, an acquisition or a technical failure costs you the whole platform, not an option premium.`,
                    coach_r3_wishlist:      `<strong>That spends past €21M — that is not a portfolio, it is a wish list.</strong> The board funds €21M and no more. Cut back into budget now, and tell us whether you cut from the cash engine you need this year or the future bet you need in 2031. Prioritisation, not ambition, is the job.`,
                    coach_r3_herobet:       `<strong>€9M into the platform and €0 into core defence is the hero bet.</strong> You have put maximum money into a bet with a ~50% failure probability and four years to revenue, and left the eroding core undefended. If it fails — and there is an even chance it does — the core has eroded faster and you have no plan B.`,
                    coach_r3_full:          `<strong>A full €9M build, funded — but with no kill point it is a vow, not a bet.</strong> You did defend the core alongside it, which saves you from the hero trap. The open question the board will ask is where your stage gate is at month 12 if the resin chemistry does not scale.`,
                    coach_r3_staged:        `<strong>Staging the bet at €6M with a 12-month kill gate is real-options discipline.</strong> You buy information before committing the rest, cap the downside, and keep the reserve as dry powder. That is how you size an H3 bet against a 45–55% success probability.`,
                    coach_r3_partner:       `<strong>Routing €6M to the NovaResin co-development funds the speed you chose in Round 2.</strong> The partnership feeds the renewal gap faster than an in-house build — and if you governed it well in Round 2, it is a protected, not an exposed, route to 2031.`,
                    coach_r3_nobet:         `<strong>Funding €0 into the bio bet defends the core and misses the mandate.</strong> Sustaining and water-based reformulation keep the engine running; they do not create new-to-2025 revenue. The renewal gap stays open and the board mandate goes unmet.`,
                    coach_r4_portfolio:     `<strong>Leading with the balanced portfolio is the story a board can fund.</strong> The core is defended, the renewal bet is sized and staged with a kill gate, and the numbers close the mandate gap. That is a portfolio decision, not a hero pitch or a hedge.`,
                    coach_r4_hero:          `<strong>Leading with the big all-in bet invites the obvious probe.</strong> You have put the company on a platform with a 50% failure probability and four years to revenue. The board will ask for your expected value and your plan B in 2028 when the bet is half-dead — and an all-in pitch has neither.`,
                    coach_r4_safe:          `<strong>Leading with prudence meets the comfort level and misses the mandate.</strong> 85% success and €14M NPV is smart and safe — but water-based reformulation defends the core; it does not renew it. The board asked for 25% new revenue by 2031, and prudence does not deliver it.`,
                    coach_r4_conviction:    `<strong>“A kill gate would signal doubt” is how an all-or-nothing bet becomes a vow.</strong> Real options are not doubt; they are discipline. Without a month-12 gate and defined milestones, you cannot act on the information the first tranche buys — and a 50% bet with no exit is a gamble.`,
                    coach_r4_cannibalseparate: `<strong>“Two separate businesses” underrates the coupling.</strong> A successful bio platform pulls customers off the solvent lines that fund 78% of the company. Treat them as separate and you will be surprised when the cash engine erodes faster than your plan assumed — the renewal you are funding eats its own funding.`,
                    coach_r4_cannibalignore: `<strong>Not modelling the core erosion is the cannibalisation blind spot.</strong> Your bio platform succeeds — wonderful — and it accelerates the decline of the solvent lines that pay for the renewal. When does the new business cover what the old one loses? If you have not modelled it, you do not know.`,

                    sum_default:            `Decision made.`,
                    sum_r1_good:            `Read the gap honestly; framed the tension as ambidexterity.`,
                    sum_r1_weak:            `Mis-sized the gap or mis-framed the central tension.`,
                    sum_r2_good:            `Partner/hybrid for speed, governed and stress-tested.`,
                    sum_r2_ungoverned:      `Signed for speed with no governance — exposed partnership.`,
                    sum_r2_none:            `Declined the bio bet — comfort-zone path.`,
                    sum_r2_weak:            `Build-vs-partner choice under-protected.`,
                    sum_r3_good:            `In-budget portfolio: core defended, bet staged.`,
                    sum_r3_wishlist:        `Spent past €21M — the wish-list error.`,
                    sum_r3_herobet:        `Full bet, no core defence — the hero trap.`,
                    sum_r3_nobet:           `No disruptive bet funded — missed the mandate.`,
                    sum_r3_weak:            `Allocation partly coherent.`,
                    sum_r4_good:            `Balanced pitch; real-options kill gate; cannibalisation modelled.`,
                    sum_r4_cannibal:        `Ignored cannibalisation of the cash engine.`,
                    sum_r4_hero:            `Pitched the all-in bet — over-betting.`,
                    sum_r4_safe:            `Pitched prudence — under-betting the mandate.`,
                    sum_r4_weak:            `Board pitch partly convincing.`,

                    insight_renewal:        `Renewal portfolio: you ran the ambidextrous play — defended the solvent core, sized and staged the bio bet with a month-12 kill gate, governed the open-innovation route, and modelled the cannibalisation. Renewal coverage closes the 2031 mandate gap on credible numbers, the core held, and the portfolio's expected value is real. That is renewal, not a graceful decline.`,
                    insight_wishlist:       `Wish list: you allocated beyond the €21M envelope. The board funds €21M and no more — a plan that spends more is not a portfolio, it is ambition without prioritisation. The discipline the role tests is what you cut, not what you would fund if money were free.`,
                    insight_herobet:        `Hero bet: you concentrated the envelope in the disruptive platform and starved the core defence, against a ~50% failure probability. Portfolio thinking beats hero bets — when the bet is half-dead in 2028 and the core has eroded faster for lack of defence, there is no plan B.`,
                    insight_incremental:    `Comfort zone: you chose the safe, high-success water-based path and under-funded the renewal bet. Defending the core is necessary but not sufficient — water-based reformulation defends, it does not renew, so the 25%-by-2031 mandate went unmet and the March board meeting did not go your way.`,
                    insight_ungoverned:     `Ungoverned partnership: you signed NovaResin for speed without a board seat, a change-of-control clause or an IP fallback. Speed bought without governance is exposure — when a competitor acquires the spin-off, the money you spent bought an option you no longer own.`,
                    insight_cannibal:       `Cannibalised core: you modelled the new platform's upside without modelling the faster erosion of the solvent core that funds it. Renewal and the core are coupled, not separate — a bio win that accelerates solvent decline eats the very cash engine paying for the renewal.`,
                    insight_mixed:          `A credible but imperfect plan: you avoided the headline traps, but the portfolio did not fully line up — the gap, the bet's sizing, the governance and the cannibalisation did not all reinforce each other, so the board is left with questions about whether the renewal is funded and safe.`,
                    insight_staged:         `You staged the disruptive bet with a kill gate rather than committing all-or-nothing — real-options discipline that buys information and caps the downside on a 45–55% bet.`,

                    hint_wishlist:          `You have spent past the €21M envelope — that reads as a wish list, not a portfolio. Cut back into budget and decide deliberately whether you trim the cash engine or the future bet.`,
                    hint_herobet:           `You have concentrated the envelope in the bio platform and left the core undefended against a ~50% failure probability. Fund the water-based defence and stage the bet so a failure is survivable.`,
                    hint_cannibal:          `You have not modelled the cannibalisation of the solvent core. A bio win accelerates the decline of the 78% of revenue that funds the renewal — model when new revenue covers the loss.`,
                    hint_ungoverned:        `Your NovaResin partnership has no governance or fallback. Add a board seat, a change-of-control clause and an IP fallback before a competitor acquisition turns your spend into nothing owned.`,
                    hint_incremental:       `You are defending the core but not renewing it. Water-based reformulation does not create new-to-2025 revenue — fund and stage a disruptive bet or the 25%-by-2031 mandate stays unmet.`,
                    hint_core:              `Core resilience is falling fast — the solvent cash engine funds the entire renewal. Defend it with the water-based programme and manage the cannibalisation before it starves the bet.`,
                    hint_strong:            `Strong position — renewal coverage is closing the gap and the core is holding. Land it: lead with the balanced portfolio, hold the month-12 kill gate, and model the cannibalisation.`,

